import React, { useState, useRef } from 'react';
import { generateSteps } from './steps';
import './Visualizer.css';

export default function Visualizer({ isRunning, isPaused, currentStep, onRunSteps, onReset, speed }) {
  const [input, setInput] = useState([5, 2, 8, 1, 9]);
  const [arraySize, setArraySize] = useState(5);

  const handleRandomize = () => {
    const newArr = Array.from({ length: arraySize }, () => Math.floor(Math.random() * 100) + 1);
    setInput(newArr);
  };

  const handleRun = () => {
    const steps = generateSteps(input);
    onRunSteps(steps);
  };

  const displayArr = currentStep?.arr || input;
  const highlightedIndices = currentStep?.indices || [];

  const getBarColor = (i) => {
    if (highlightedIndices.includes(i)) {
      if (currentStep?.type === 'swap') return '#ff6b6b';
      if (currentStep?.type === 'compare') return '#ffd93d';
      return '#4dabf7';
    }
    return '#7dd3fc';
  };

  return (
    <div className="heap-visualizer">
      {/* Controls */}
      <div className="viz-controls-panel">
        <div className="control-group">
          <label>Array Size: {arraySize}</label>
          <input
            type="range"
            min="3"
            max="12"
            value={arraySize}
            onChange={(e) => setArraySize(parseInt(e.target.value))}
            disabled={isRunning}
          />
        </div>

        <div className="control-group">
          <label>Values (comma-separated):</label>
          <input
            type="text"
            value={input.join(', ')}
            onChange={(e) => setInput(e.target.value.split(',').map(x => parseInt(x.trim()) || 0))}
            placeholder="5, 2, 8, 1, 9"
            disabled={isRunning}
          />
        </div>

        <div className="control-buttons">
          <button onClick={handleRandomize} disabled={isRunning} className="btn-secondary">
            🎲 Random
          </button>
          <button onClick={handleRun} disabled={isRunning} className="btn-primary">
            ▶ Run Heap Sort
          </button>
          <button onClick={onReset} disabled={isRunning} className="btn-secondary">
            ↺ Reset
          </button>
        </div>
      </div>

      {/* Visualization */}
      <div className="viz-display">
        <div className="bars-container">
          {displayArr.map((val, i) => (
            <div key={i} className="bar-wrapper">
              <div
                className="bar"
                style={{
                  height: `${(val / Math.max(...displayArr, 100)) * 100}%`,
                  backgroundColor: getBarColor(i),
                  transition: 'all 0.1s ease',
                }}
              />
              <div className="bar-label">{val}</div>
            </div>
          ))}
        </div>

        {currentStep?.msg && (
          <div className="viz-message">
            <div className="msg-text">{currentStep.msg}</div>
            <div className="msg-stats">
              Comparisons: <strong>{currentStep.comparisons || 0}</strong> | Swaps: <strong>{currentStep.swaps || 0}</strong>
            </div>
          </div>
        )}
      </div>

      {/* Heap Tree View (optional) */}
      <div className="heap-info">
        <p style={{ fontSize: '11px', color: '#7dd3fc' }}>
          💡 <strong>Heap Structure:</strong> Index i has left child at 2i+1, right child at 2i+2
        </p>
      </div>
    </div>
  );
}
